          anchor: 'ο ελληνικός εμπορικός στόλος μετατράπηκε σε πολεμικό, οι δρόμοι του εμπορίου έκλεισαν',
          hook: 'Δεν βυθίστηκε ο στόλος — ΑΛΛΑΞΕ ΔΟΥΛΕΙΑ. Ένα εμπορικό που κουβαλάει κανόνια δεν κουβαλάει εμπόρευμα, και ένα λιμάνι σε πόλεμο δεν έχει πελάτες. Δύο απώλειες από μία αιτία.',
