          anchor: 'Το πιο σημαντικό απ’ αυτά ήταν η Σύρος',
          hook: '⭐ ΠΡΟΣΕΞΕ ΤΗ ΣΕΙΡΑ ΑΙΤΙΑΣ: πρώτα ήρθαν οι ΑΝΘΡΩΠΟΙ και μετά έγινε το λιμάνι. Η καταστροφή της Χίου (1822) γέμισε τη Σύρο με εμπόρους και ναυτικούς που είχαν χάσει τα πάντα εκτός από τη δουλειά που ήξεραν — ακριβώς η «γνώση των ναυτικών υποθέσεων» του προηγούμενου σημείου, να μετακομίζει.',
