          anchor: 'Το 1919 ο ελληνικός εμπορικός στόλος είχε υποδιπλασιαστεί',
          hook: '⭐⭐ ΤΟ ΤΕΛΟΣ ΤΗΣ ΥΠΟΕΝΟΤΗΤΑΣ ΕΙΝΑΙ Η ΑΡΧΗ ΤΗΣ, ΞΑΝΑ. Άρχισε με «ακολούθησαν δύσκολα χρόνια» και κλείνει με «στην ουσία χρειάστηκε μια νέα αρχή». Δύο καταστροφές, μία στην αρχή και μία στο τέλος, και ανάμεσά τους μια ολόκληρη ανοικοδόμηση. ⚠️ Πρόσεξε τα δύο έτη μαζί: υποδιπλασιάστηκε ΤΟ 1919 ΣΕ ΣΧΕΣΗ ΜΕ ΤΟ 1914 — χωρίς το δεύτερο δεν λες τίποτα.',
