      { t: 'Πώς λέγεται η πόλη της Σύρου', d: 'Ερμούπολη. Την έχεις ήδη δει στον Πίνακα 2 της α΄ υποενότητας: 22.000 κάτοικοι το 1879 και το 1889, 18.000 το 1907 — δηλαδή στην κορυφή της ήταν από τις μεγαλύτερες πόλεις της χώρας και μετά έπεφτε, καθώς ο Πειραιάς την προσπερνούσε (22.000 → 74.000 στο ίδιο διάστημα). ⚠️ Το όνομα «Ερμούπολη» ΔΕΝ γράφεται σε αυτή την παράγραφο.' },
      { t: 'Τι ακολουθεί', d: 'Η επόμενη υποενότητα είναι η «3. Η διανομή των εθνικών κτημάτων». ✅ ΑΝΑΤΕΘΗΚΕ — είναι πλέον δική σου ύλη, στη σελίδα δίπλα.' }
