            { k: 'δεν ήταν στις προθέσεις των πλουσίων', say: [['προθεσεισ των πλουσιων'], ['πλουσιων']] },
            { k: 'γεγονός που άμβλυνε τις αντιθέσεις', say: [['αμβλυνε'], ['αντιθεσεισ']] },
            { k: 'δεν επέτρεψε σημαντικές κοινωνικές εντάσεις', say: [['κοινωνικεσ εντασεισ'], ['επετρεψ', 'εντασ']] }
